CREATE TABLE [purchase].[PurchaseInvoiceItems]([PurchaseItemId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_PurchaseItems_Id] DEFAULT NEWSEQUENTIALID(),[PurchaseInvoiceId] UNIQUEIDENTIFIER NOT NULL,[ProductId] UNIQUEIDENTIFIER NOT NULL,[Barcode] NVARCHAR(100) NULL,[BatchNo] NVARCHAR(100) NULL,[ExpiryDate] DATE NULL,[Quantity] DECIMAL(18,4) NOT NULL,[FreeQuantity] DECIMAL(18,4) NOT NULL CONSTRAINT [DF_PurchaseItems_Free] DEFAULT 0,[ReturnedQuantity] DECIMAL(18,4) NOT NULL CONSTRAINT [DF_PurchaseItems_Returned] DEFAULT 0,[PurchasePrice] DECIMAL(18,4) NOT NULL,[MRP] DECIMAL(18,4) NOT NULL,[SellingPrice] DECIMAL(18,4) NOT NULL,[DiscountPercentage] DECIMAL(5,2) NOT NULL CONSTRAINT [DF_PurchaseItems_DiscountPct] DEFAULT 0,[DiscountAmount] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_PurchaseItems_Discount] DEFAULT 0,[GSTPercentage] DECIMAL(5,2) NOT NULL,[GSTAmount] DECIMAL(18,2) NOT NULL,[AllocatedExpense] DECIMAL(18,2) NOT NULL CONSTRAINT [DF_PurchaseItems_Expense] DEFAULT 0,[LineTotal] DECIMAL(18,2) NOT NULL,CONSTRAINT [PK_PurchaseInvoiceItems] PRIMARY KEY([PurchaseItemId]),CONSTRAINT [FK_PurchaseItems_Invoice] FOREIGN KEY([PurchaseInvoiceId]) REFERENCES [purchase].[PurchaseInvoices]([PurchaseInvoiceId]) ON DELETE CASCADE,CONSTRAINT [FK_PurchaseItems_Product] FOREIGN KEY([ProductId]) REFERENCES [master].[Products]([ProductId]),CONSTRAINT [CK_PurchaseItems_Quantity] CHECK([Quantity]>0 AND [FreeQuantity]>=0),CONSTRAINT [CK_PurchaseItems_Prices] CHECK([PurchasePrice]>=0 AND [MRP]>=[SellingPrice]),CONSTRAINT [CK_PurchaseItems_GST] CHECK([GSTPercentage] BETWEEN 0 AND 100));
GO
CREATE INDEX [IX_PurchaseItems_Product] ON [purchase].[PurchaseInvoiceItems]([ProductId],[BatchNo],[ExpiryDate]);
